public class JadePlugin
implements IWailaPlugin {
    private static final ResourceLocation[] CHEMICALS = new ResourceLocation[]{new ResourceLocation("mekanism", "gas"), new ResourceLocation("mekanism", "infuse_type"), new ResourceLocation("mekanism", "pigment"), new ResourceLocation("mekanism", "slurry")};

    public void register(IWailaCommonRegistration registration) {
        registration.registerBlockDataProvider((IServerDataProvider)JadeDateSender.INSTANCE, BlockEntity.class);
    }

    public void registerClient(IWailaClientRegistration registration) {
        registration.registerBlockComponent((IBlockComponentProvider)WirelessConnectorTooltip.INSTANCE, Block.class);
        registration.registerBlockComponent((IBlockComponentProvider)CrystalGrowthChamberTooltip.INSTANCE, Block.class);
        registration.addTooltipCollectedCallback((tooltip, accessor) -> {
            Object target = accessor.getTarget();
            for (ResourceLocation loc : CHEMICALS) {
                if (!(target instanceof TileIngredientBuffer) && !(target instanceof TileCaner) && !(target instanceof TileCircuitCutter)) continue;
                tooltip.remove(loc);
            }
        });
    }
}

